import re


def bulk_discount(qty):
    if qty >= 100:
        return 0.12
    if qty >= 20:
        return 0.04
    return 0.0


def line_total(unit_price, qty):
    return round(unit_price * qty * (1 - bulk_discount(qty)), 2)


_SKU_RE = re.compile(r"^([A-Z]{2,4}):(\d{4}):([A-Z])$")


def parse_sku(s):
    if not isinstance(s, str):
        raise ValueError("invalid SKU: %r" % (s,))
    m = _SKU_RE.fullmatch(s)
    if m is None:
        raise ValueError("invalid SKU: %r" % (s,))
    return {"category": m.group(1), "number": int(m.group(2)), "variant": m.group(3)}

"""Shipping helpers: zone lookup, cost calculation, and oversize check."""

_BASE_BY_ZONE = {1: 5.0, 2: 12.0, 3: 25.0}


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    1 for US, 2 for CA or MX, 3 for any other code.
    """
    if country_code == "US":
        return 1
    if country_code in ("CA", "MX"):
        return 2
    return 3


def shipping_cost(weight_kg, zone):
    """Return base + 2.0 * weight_kg, rounded to 2 decimals.

    Base is 5.0 for zone 1, 12.0 for zone 2, and 25.0 for zone 3.
    """
    base = _BASE_BY_ZONE[zone]
    return round(base + 2.0 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 150 or l + w + h exceeds 360."""
    return l > 150 or w > 150 or h > 150 or (l + w + h) > 360

